steps.command:
# 1. Encontrar archivos o carpetas vacías de tamaño cero con -empty
find /tmp/lab103 -empty

# 2. Buscar archivos excluyendo una extensión con -not (o !)
find /tmp/lab103 -type f -not -name "*.tar.*"

# 3. Ejecutar comando sobre cada coincidencia con -exec y cierre escapado \;
find /tmp/lab103 -name "*.txt" -exec ls -lh {} \;
